import{_ as o,o as a,c as e,ag as d}from"./chunks/framework.C9sp7nFj.js";const _=JSON.parse('{"title":"MovToIPos 返回中断点","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/15. 中断指令/MovToIPos.md","filePath":"3. 指令/15. 中断指令/MovToIPos.md","lastUpdated":1778862643000}'),r={name:"3. 指令/15. 中断指令/MovToIPos.md"};function s(l,t,i,n,h,p){return a(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="movtoipos-返回中断点" tabindex="-1">MovToIPos 返回中断点 <a class="header-anchor" href="#movtoipos-返回中断点" aria-label="Permalink to &quot;MovToIPos 返回中断点&quot;">​</a></h1><p>该指令为返回中断点指令，以指定的运动形式使机器人自动回到主程序被中断的位置，中断发生时系统会自动缓存中断位置点，本指令执行时会自动从内存中取出该中断位置点并运行到该中断位置点。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovToIPos(Mode, V)</p><p>MovToIPos(运动方式, 目标速度)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>Mode</td><td>enum(MOVJ/MOVL)</td><td>运动到中断点的运动方式：MOVJ 为关节运动，MOVL 为直线运动</td><td>必填</td></tr><tr><td>V</td><td>SPEED</td><td>运动到中断点的速度</td><td>必填</td></tr></tbody></table><blockquote><p><strong>备注：</strong></p><ol><li>该指令只能在中断程序中执行。</li><li>该指令必须与 IEnter、IExit 指令搭配使用。</li></ol></blockquote>',9)])])}const P=o(r,[["render",s]]);export{_ as __pageData,P as default};
